import numpy as np
from scipy.optimize import minimize

def f(vars):
    x, y, z = vars
    if x <= 0 or y <= 0 or z <= 0:
        return 1e9
    return (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1) / (x*y + y*z + z*x)

# Search for a minimum point by trying many different starting points
min_vals = []
for x0 in np.linspace(0.1, 10, 10):
    for y0 in np.linspace(0.1, 10, 10):
        for z0 in np.linspace(0.1, 10, 10):
            res = minimize(f, [x0, y0, z0], bounds=((1e-6, None), (1e-6, None), (1e-6, None)))
            if res.success:
                min_vals.append(res.fun)

print(f"Minimum found: {min(min_vals)}")

